function longestWithEdits(s: string, k: number): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const count = new Array(26).fill(0);
    let top = 0;
    for (let j = i; j < s.length; j++) {
      const c = s.charCodeAt(j) - 65;
      top = Math.max(top, ++count[c]);
      if (j - i + 1 - top <= k) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

