function longestWithEdits(s: string, k: number): number {
  let best = 0;
  for (const letter of new Set(s)) {
    let start = 0, others = 0;
    for (let end = 0; end < s.length; end++) {
      if (s[end] !== letter) others++;
      while (others > k) {
        if (s[start] !== letter) others--;
        start++;
      }
      best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

