function longestWithEdits(s: string, k: number): number {
  const count = new Array(26).fill(0);
  let start = 0, maxFreq = 0, best = 0;
  for (let end = 0; end < s.length; end++) {
    const c = s.charCodeAt(end) - 65;
    count[c]++;
    maxFreq = Math.max(maxFreq, count[c]);
    if (end - start + 1 - maxFreq > k) {
      // too many edits: slide the window right by one, keeping its length
      count[s.charCodeAt(start) - 65]--;
      start++;
    }
    best = Math.max(best, end - start + 1);
  }
  return best;
}

